// native_rave_register.cpp — registers every native of native_rave_decl.h with
// bronze (embed::registerNative) under __bro_native.rave. Generated by brosurface
// (gen/emit_natives.mjs); do not edit. Call registerNatives_rave from registerBroNatives
// (src/bronze_host/host_natives.h) on the thread that runs the program.
//
// Class members are Function-kind natives taking the handle first (the wrapper's
// receiver is dynamic, so a Method-kind registration would be unreachable from it);
// each class has one Constructor-kind registration, which mints the class, and its
// prototype is published as __bro_native.rave.<Class>Proto for rave.js to chain.

#include "native_rave_decl.h"

#include "embed/embed.h"

#include <initializer_list>
#include <string>

namespace bro::bronze_host {

namespace {

namespace ev = bronze::embed;

ev::NativeSignature sig(const char* ret, std::initializer_list<const char*> params, ev::NativeKind kind) {
    ev::NativeSignature s;
    s.returnType = ret;
    for (const char* p : params) s.paramTypes.emplace_back(p);
    s.kind = kind;
    return s;
}

bool fn(const char* path, void* f, const char* ret, std::initializer_list<const char*> params, std::string* error) {
    return ev::registerNative(path, f, sig(ret, params, ev::NativeKind::Function), error);
}

bool ctor(const char* path, void* f, ev::HandleDestructor dtor, bronze::runtime::Finalize finalize,
          std::initializer_list<const char*> params, std::string* error) {
    ev::NativeSignature s = sig(path, params, ev::NativeKind::Constructor);
    s.className = path;
    s.destructor = dtor;
    s.finalize = finalize;
    return ev::registerNative(path, f, s, error);
}

// The prototype every instance of a class is born on, published where the
// wrapper reads it. Skipped when the roots are not there (bro-native-manifest
// registers without them; the manifest does not need the prototype).
void publishPrototype(const char* ns, const char* className, const char* protoName) {
    ev::GlobalValue root = ev::globalValue("__bro_native");
    if (!root.found || !ev::isObject(root.value)) return;
    ev::GlobalValue proto = ev::nativeClassPrototype(className);
    if (!proto.found) return;
    // Each value rooted before the next allocating call (bronze embed GC contract).
    ev::Persistent rootSlot(root.value);
    ev::Persistent protoSlot(proto.value);
    ev::Persistent nsSlot(ev::getProperty(rootSlot.get(), ns));
    if (!ev::isObject(nsSlot.get())) return;
    ev::setProperty(nsSlot.get(), protoName, protoSlot.get());
}

template <typename F>
void* p(F* f) { return reinterpret_cast<void*>(f); }

}  // namespace

bool registerNatives_rave(std::string* error) {
    bool ok =
        ctor("__bro_native.rave.Rave", p(&bro_rave_Rave_ctor), &bro_rave_Rave_dtor, bronze::runtime::Finalize::InSweep, {}, error) &&
        fn("__bro_native.rave.Rave_loaded_get", p(&bro_rave_Rave_loaded_get), "bool", {"__bro_native.rave.Rave"}, error) &&
        fn("__bro_native.rave.Rave_sampleRate_get", p(&bro_rave_Rave_sampleRate_get), "i32", {"__bro_native.rave.Rave"}, error) &&
        fn("__bro_native.rave.Rave_nLatent_get", p(&bro_rave_Rave_nLatent_get), "i32", {"__bro_native.rave.Rave"}, error) &&
        fn("__bro_native.rave.Rave_fullLatent_get", p(&bro_rave_Rave_fullLatent_get), "i32", {"__bro_native.rave.Rave"}, error) &&
        fn("__bro_native.rave.Rave_nBand_get", p(&bro_rave_Rave_nBand_get), "i32", {"__bro_native.rave.Rave"}, error) &&
        fn("__bro_native.rave.Rave_totalRatio_get", p(&bro_rave_Rave_totalRatio_get), "i32", {"__bro_native.rave.Rave"}, error) &&
        fn("__bro_native.rave.Rave_encode", p(&bro_rave_Rave_encode), "void", {"__bro_native.rave.Rave", "f32[]"}, error) &&
        fn("__bro_native.rave.Rave_encode_latent", p(&bro_rave_Rave_encode_latent), "f32[]", {}, error) &&
        fn("__bro_native.rave.Rave_encode_nLatent", p(&bro_rave_Rave_encode_nLatent), "i32", {}, error) &&
        fn("__bro_native.rave.Rave_encode_frames", p(&bro_rave_Rave_encode_frames), "i32", {}, error) &&
        fn("__bro_native.rave.Rave_decode", p(&bro_rave_Rave_decode), "void", {"__bro_native.rave.Rave", "f32[]", "i32", "bool", "bool", "f64", "i32", "f64"}, error) &&
        fn("__bro_native.rave.Rave_decode_samples", p(&bro_rave_Rave_decode_samples), "f32[]", {}, error) &&
        fn("__bro_native.rave.Rave_decode_sampleRate", p(&bro_rave_Rave_decode_sampleRate), "i32", {}, error) &&
        fn("__bro_native.rave.Rave_decode_channels", p(&bro_rave_Rave_decode_channels), "i32", {}, error);
#if BRO_WITH_SOUNDML
    ok = ok &&
        fn("__bro_native.rave.init", p(&bro_rave_init), "void", {}, error) &&
        fn("__bro_native.rave.loadRave", p(&bro_rave_loadRave), "__bro_native.rave.Rave", {"str", "bool", "str", "dynamic", "dynamic"}, error);
#endif
    if (!ok) return false;
    publishPrototype("rave", "__bro_native.rave.Rave", "RaveProto");
    return true;
}

}  // namespace bro::bronze_host
